changeSet.sql:
ALTER TABLE order_status_history
    ADD COLUMN tx_id UUID,
    ADD COLUMN tx_state TEXT NOT NULL DEFAULT 'CONFIRMED';

CREATE UNIQUE INDEX idx_order_status_history_tx_id
    ON order_status_history(tx_id)
    WHERE tx_id IS NOT NULL;

CREATE INDEX idx_order_status_history_tx_state
    ON order_status_history(tx_state);
